// Copies Google's <model-viewer> web component into a TypeScript module so
// the 3D viewer's WebView works without internet.
//
//   npm run vendor
//
// Re-run after upgrading the @google/model-viewer dev dependency.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const pkg = require('@google/model-viewer/package.json');
const source = readFileSync(require.resolve('@google/model-viewer/dist/model-viewer-umd.min.js'), 'utf8')
  // Strip the source map comment; the map is not shipped.
  .replace(/\/\/# sourceMappingURL=.*$/m, '')
  // Keep the script from closing the inline <script> tag it is placed in.
  .replace(/<\/script/gi, '<\\/script');

const output = resolve(root, 'src/viewer/generated/modelViewerLib.ts');
mkdirSync(dirname(output), { recursive: true });
writeFileSync(
  output,
  `// Generated by scripts/embed-model-viewer.mjs from @google/model-viewer ${pkg.version} (Apache-2.0).\n` +
    '// Do not edit by hand; run `npm run vendor` instead.\n' +
    `export const MODEL_VIEWER_VERSION = '${pkg.version}';\n` +
    `export const MODEL_VIEWER_SCRIPT = ${JSON.stringify(source)};\n`,
);
console.log(`Wrote model-viewer ${pkg.version} to ${output.replace(root + '/', '')}`);
